//! Integration tests: `--replay` over each platform's saved raw-API-response
//! fixture must produce EXACTLY the NDJSON the Python twin's `normalize.py`
//! emits for the same objects — byte-for-byte (the expected strings below were
//! generated by running the actual Python normalizers over the fixtures) —
//! plus the deterministic synthetic `observed_at_ns` stamp (§22: replay is a
//! pure function of the fixture file; NO test touches the network). Missing
//! credentials must refuse to start with the Python twins' exact stderr
//! messages, before any socket could be opened.

use std::process::{Command, Output};

use pq_social_capture::json;

/// Fixed replay clock (must mirror `REPLAY_BASE_NS`/`REPLAY_STEP_NS`).
const BASE: u64 = 1_000_000_000;
const STEP: u64 = 1_000_000;

fn fixture(name: &str) -> String {
    format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"))
}

/// Run the binary with the given args and ALL adapter credentials scrubbed
/// from the environment — proof that replay (and refusal) is keyless.
fn run(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_pq-social-capture"))
        .args(args)
        .env_remove("TWITTERAPI_IO_KEY")
        .env_remove("TIKTOK_API_KEY")
        .env_remove("TIKTOK_API_BASE")
        .env_remove("FIRECRAWL_API_KEY")
        .output()
        .expect("binary runs")
}

fn stdout_lines(out: &Output) -> Vec<String> {
    String::from_utf8(out.stdout.clone())
        .expect("stdout is UTF-8")
        .lines()
        .map(String::from)
        .collect()
}

/// Splice the synthetic capture stamp into a `normalize.py`-shaped line —
/// the expected strings stay verbatim Python output.
fn with_stamp(python_line: &str, i: u64) -> String {
    let ts = BASE + i * STEP;
    format!(
        "{},\"observed_at_ns\":{ts}}}",
        python_line.strip_suffix('}').expect("object line")
    )
}

// ---------------------------------------------------------------- twitterapi

/// Verbatim `normalize.py` output for twitterapi_pages.json (dedupe applied),
/// generated by the Python twin's own `normalize_tweet`.
const TWITTER_EXPECTED: [&str; 4] = [
    "{\"platform\":\"x\",\"author\":\"cryptoKOL\",\"community\":\"\",\"text\":\"send it $WIF EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v\",\"likes\":420,\"reposts\":69,\"replies\":12,\"echo\":false}",
    "{\"platform\":\"x\",\"author\":\"echoAcct\",\"community\":\"\",\"text\":\"RT $WIF to the moon \u{1F680}\",\"likes\":2,\"reposts\":0,\"replies\":0,\"echo\":true}",
    "{\"platform\":\"x\",\"author\":\"unknown\",\"community\":\"\",\"text\":\"quote pumping \\\"hard\\\"\",\"likes\":7,\"reposts\":0,\"replies\":1,\"echo\":true}",
    "{\"platform\":\"x\",\"author\":\"replyGuy\",\"community\":\"\",\"text\":\"replying about $BONK\",\"likes\":0,\"reposts\":0,\"replies\":0,\"echo\":true}",
];

#[test]
fn twitterapi_replay_is_byte_exact_python_output() {
    let out = run(&["twitterapi", "--replay", &fixture("twitterapi_pages.json")]);
    assert!(out.status.success(), "{out:?}");
    let lines = stdout_lines(&out);
    let expected: Vec<String> = TWITTER_EXPECTED
        .iter()
        .enumerate()
        .map(|(i, l)| with_stamp(l, i as u64))
        .collect();
    assert_eq!(
        lines,
        expected,
        "stderr: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    // The duplicate id on page 2 was deduplicated across polls: 5 raw tweets
    // in the fixture, 4 emitted.
    assert!(String::from_utf8_lossy(&out.stderr).contains("replay: emitted 4 events"));
}

#[test]
fn twitterapi_replay_is_deterministic_across_runs() {
    let a = run(&["twitterapi", "--replay", &fixture("twitterapi_pages.json")]);
    let b = run(&["twitterapi", "--replay", &fixture("twitterapi_pages.json")]);
    assert_eq!(a.stdout, b.stdout, "byte-identical replays (§22)");
}

