// ----------------------------------------------------------------- firecrawl

/// Verbatim `normalize.py` output for firecrawl_scrape.json (the third saved
/// response has an empty markdown and emits nothing, like the Python `if md:`).
const FIRECRAWL_EXPECTED: [&str; 2] = [
    "{\"platform\":\"web\",\"author\":\"www.dexscreener.com\",\"community\":\"www.dexscreener.com\",\"text\":\"# Trending on Solana\\n\\n$WIF EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v and $BONK\",\"likes\":0,\"reposts\":0,\"replies\":0,\"echo\":false}",
    "{\"platform\":\"web\",\"author\":\"www.dexscreener.com\",\"community\":\"www.dexscreener.com\",\"text\":\"top-level content fallback $PONKE\",\"likes\":0,\"reposts\":0,\"replies\":0,\"echo\":false}",
];

#[test]
fn firecrawl_replay_is_byte_exact_python_output() {
    let out = run(&[
        "firecrawl",
        "--url",
        "https://www.dexscreener.com/solana",
        "--replay",
        &fixture("firecrawl_scrape.json"),
    ]);
    assert!(out.status.success(), "{out:?}");
    let lines = stdout_lines(&out);
    let expected: Vec<String> = FIRECRAWL_EXPECTED
        .iter()
        .enumerate()
        .map(|(i, l)| with_stamp(l, i as u64))
        .collect();
    assert_eq!(
        lines,
        expected,
        "stderr: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(String::from_utf8_lossy(&out.stderr).contains("replay: emitted 2 events"));
}

#[test]
fn firecrawl_replay_without_urls_refuses_like_python() {
    // No --url and no sources.yaml in the test cwd: the Python twin's exact
    // message and exit code.
    let out = run(&["firecrawl", "--replay", &fixture("firecrawl_scrape.json")]);
    assert_eq!(out.status.code(), Some(2));
    assert!(String::from_utf8_lossy(&out.stderr)
        .contains("no pages configured (sources.yaml web.pages) and no --url"));
    assert!(
        out.stdout.is_empty(),
        "stdout stays NDJSON-only (nothing here)"
    );
}

// ----------------------------------------------------- credentials + hygiene

#[test]
fn missing_credentials_refuse_with_python_twin_messages() {
    let cases: [(&[&str], &str); 3] = [
        (
            &["twitterapi"],
            "error: set TWITTERAPI_IO_KEY (https://twitterapi.io, pay-as-you-go)",
        ),
        (
            &["tiktok"],
            "error: set TIKTOK_API_KEY and TIKTOK_API_BASE (your provider endpoint)",
        ),
        (
            &["firecrawl", "--url", "https://pump.fun/board"],
            "error: set FIRECRAWL_API_KEY (https://firecrawl.dev)",
        ),
    ];
    for (args, msg) in cases {
        let out = run(args);
        assert_eq!(out.status.code(), Some(2), "{args:?}");
        let stderr = String::from_utf8_lossy(&out.stderr);
        assert!(stderr.contains(msg), "{args:?} stderr: {stderr}");
        assert!(out.stdout.is_empty(), "{args:?} must not write stdout");
    }
}

#[test]
fn unknown_subcommand_exits_2_with_usage() {
    let out = run(&["telegram"]);
    assert_eq!(out.status.code(), Some(2));
    assert!(String::from_utf8_lossy(&out.stderr).contains("unknown subcommand"));
}

#[test]
fn every_replay_line_round_trips_as_valid_json_with_schema_order() {
    for (args, platform) in [
        (
            vec!["twitterapi", "--replay", &*fixture("twitterapi_pages.json")],
            "x",
        ),
        (
            vec!["tiktok", "--replay", &*fixture("tiktok_feed.json")],
            "tiktok",
        ),
        (
            vec![
                "firecrawl",
                "--url",
                "https://pump.fun/board",
                "--replay",
                &*fixture("firecrawl_scrape.json"),
            ],
            "web",
        ),
    ] {
        let out = run(&args);
        assert!(out.status.success(), "{args:?}");
        for line in stdout_lines(&out) {
            let v = json::parse(&line).unwrap_or_else(|e| panic!("invalid JSON {line:?}: {e}"));
            // Round-trip: re-serializing must reproduce the emitted bytes
            // exactly (proves the hand-rolled escape fn is canonical).
            assert_eq!(json::serialize(&v), line, "round-trip drift");
            let json::Value::Object(pairs) = &v else {
                panic!("top level must be an object");
            };
            let keys: Vec<&str> = pairs.iter().map(|(k, _)| k.as_str()).collect();
            // Exactly the normalize.py fields, in normalize.py order, plus the
            // capture stamp — the contract the deterministic core consumes.
            assert_eq!(
                keys,
                [
                    "platform",
                    "author",
                    "community",
                    "text",
                    "likes",
                    "reposts",
                    "replies",
                    "echo",
                    "observed_at_ns"
                ]
            );
            assert_eq!(
                pairs[0].1,
                json::Value::String(platform.to_string()),
                "platform tag"
            );
        }
    }
}
